rss.channel:
{% assign locale = site.t[page.lang] %}
{{ locale.title | xml_escape }}
{{ locale.subtitle | xml_escape }}
{{ page.lang }}
{{ locale.home.url | absolute_url | xml_escape }}

{{ site.time | date_to_rfc822 }}
Jekyll v{{ jekyll.version }}
{% if page.tag %}
  {% assign source_posts = site.tags[page.tag] %}
{% else %}
  {% assign source_posts = site.posts %}
{% endif %}
{% assign posts = source_posts | where: 'lang', page.lang %}
{% for post in posts limit:10 %}


    {{ post.title | xml_escape }}
    {{ post.content | xml_escape }}
    {{ post.date | date_to_rfc822 }}
    {{ post.url | absolute_url | xml_escape }}
    {% comment %}These identifiers must stay stable when links change.{% endcomment %}
    {{ post.url | prepend: site.baseurl | prepend: site.legacy_rss_guid_base | xml_escape }}
    {% for tag in post.tags %}
      {{ tag | xml_escape }}
    {% endfor %}
    {% for category in post.categories %}
      {{ category | xml_escape }}
    {% endfor %}

{% endfor %}
